-- ---- functions the tables need (triggers, checks); bodies are not checked until tables exist
-- update_updated_at_column
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$;

-- catalog_bump_version
CREATE OR REPLACE FUNCTION public.catalog_bump_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.version := 1;
    ELSE
        NEW.version := OLD.version + 1;
    END IF;
    NEW.updated_at := NOW();
    RETURN NEW;
END;
$function$;

-- environment_policies_normalise_url
CREATE OR REPLACE FUNCTION public.environment_policies_normalise_url()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.environment_base_url := public.normalise_environment_url(NEW.environment_base_url);
    IF NEW.environment_base_url IS NULL THEN
        RAISE EXCEPTION 'environment_base_url must be an absolute URL with a scheme (e.g. https://tenant.example.com)';
    END IF;
    RETURN NEW;
END;
$function$;

-- normalise_environment_url
CREATE OR REPLACE FUNCTION public.normalise_environment_url(p_url text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    v_url TEXT;
    v_scheme TEXT;
    v_host TEXT;
BEGIN
    IF p_url IS NULL THEN
        RETURN NULL;
    END IF;

    v_url := LOWER(TRIM(p_url));

    -- Require an explicit scheme; without one we cannot tell host from path.
    IF POSITION('://' IN v_url) = 0 THEN
        RETURN NULL;
    END IF;

    v_scheme := SPLIT_PART(v_url, '://', 1);
    -- Everything after the FIRST '://' (a path may legally contain another).
    v_host := SUBSTRING(v_url FROM POSITION('://' IN v_url) + 3);

    -- Strip userinfo (everything up to and including the last '@' before the
    -- first '/'), then path/query/fragment, then port.
    v_host := REGEXP_REPLACE(v_host, '^[^/]*@', '');
    v_host := SPLIT_PART(v_host, '/', 1);
    v_host := SPLIT_PART(v_host, '?', 1);
    v_host := SPLIT_PART(v_host, '#', 1);
    v_host := SPLIT_PART(v_host, ':', 1);

    IF v_scheme = '' OR v_host = '' THEN
        RETURN NULL;
    END IF;

    RETURN v_scheme || '://' || v_host;
END;
$function$;

-- current_week_start
CREATE OR REPLACE FUNCTION public.current_week_start()
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
    RETURN DATE_TRUNC('week', NOW())::DATE;
END;
$function$;

-- get_effective_license
CREATE OR REPLACE FUNCTION public.get_effective_license(p_user_id uuid, p_environment_url text DEFAULT NULL::text)
 RETURNS TABLE(license_type text, status text, access_level text, trial_ends_at timestamp with time zone, subscription_ends_at timestamp with time zone, licensed_environment_urls text[], is_lifetime boolean, cancel_at_period_end boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_env_urls TEXT[];
    v_specific_env_match BOOLEAN := FALSE;
BEGIN
    -- Environment URLs owned by THIS user only (for display). Never anyone else's.
    SELECT ARRAY_AGG(DISTINCT el.environment_base_url)
    INTO v_user_env_urls
    FROM public.environment_licenses el
    JOIN public.user_licenses ul ON ul.id = el.license_id
    WHERE ul.user_id = p_user_id
      AND ul.status = 'active'
      AND ul.license_type = 'environment'
      AND (ul.subscription_ends_at IS NULL OR ul.subscription_ends_at > NOW());

    v_user_env_urls := COALESCE(v_user_env_urls, ARRAY[]::TEXT[]);

    IF p_environment_url IS NOT NULL THEN
        -- Open environment: full access for everyone (the Training Ground).
        PERFORM 1 FROM public.open_environments oe
        WHERE oe.environment_base_url = p_environment_url;

        IF FOUND THEN
            v_specific_env_match := TRUE;
        ELSE
            -- Licensed by ANY user: anyone connecting to a licensed environment gets
            -- full access. This is how environment licensing works.
            PERFORM 1
            FROM public.environment_licenses el
            JOIN public.user_licenses ul ON ul.id = el.license_id
            WHERE el.environment_base_url = p_environment_url
              AND ul.status = 'active'
              AND ul.license_type = 'environment'
              AND (ul.subscription_ends_at IS NULL OR ul.subscription_ends_at > NOW())
            LIMIT 1;

            IF FOUND THEN
                v_specific_env_match := TRUE;
            END IF;
        END IF;
    END IF;

    -- 1. Active user licence (user tier or trial)
    RETURN QUERY
    SELECT
        ul.license_type,
        ul.status,
        'full'::TEXT AS access_level,
        ul.trial_ends_at,
        ul.subscription_ends_at,
        v_user_env_urls AS licensed_environment_urls,
        ul.is_lifetime,
        ul.cancel_at_period_end
    FROM public.user_licenses ul
    WHERE ul.user_id = p_user_id
      AND ul.status = 'active'
      AND ul.license_type IN ('user', 'trial')
      AND (
          (ul.license_type = 'trial' AND ul.trial_ends_at > NOW())
          OR (ul.license_type = 'user' AND (ul.subscription_ends_at IS NULL OR ul.subscription_ends_at > NOW()))
      )
    ORDER BY ul.created_at DESC
    LIMIT 1;

    IF FOUND THEN
        RETURN;
    END IF;

    -- 2. The environment being used is open or licensed
    IF v_specific_env_match THEN
        RETURN QUERY
        SELECT
            'environment'::TEXT AS license_type,
            'active'::TEXT AS status,
            'full'::TEXT AS access_level,
            NULL::TIMESTAMPTZ AS trial_ends_at,
            NULL::TIMESTAMPTZ AS subscription_ends_at,
            v_user_env_urls AS licensed_environment_urls,
            FALSE AS is_lifetime,
            FALSE AS cancel_at_period_end;
        RETURN;
    END IF;

    -- 3. Free tier
    RETURN QUERY
    SELECT
        'free'::TEXT AS license_type,
        'active'::TEXT AS status,
        'limited'::TEXT AS access_level,
        NULL::TIMESTAMPTZ AS trial_ends_at,
        NULL::TIMESTAMPTZ AS subscription_ends_at,
        v_user_env_urls AS licensed_environment_urls,
        FALSE AS is_lifetime,
        FALSE AS cancel_at_period_end;
END;
$function$;

-- get_telemetry_stats
CREATE OR REPLACE FUNCTION public.get_telemetry_stats(p_user_id uuid)
 RETURNS TABLE(period text, total_batch_runs bigint, total_batch_records bigint, total_api_calls bigint, total_execution_time_ms bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    -- Weekly stats (Monday-based week)
    RETURN QUERY
    SELECT
        'weekly'::TEXT AS period,
        COALESCE(SUM(te.batch_runs), 0)::BIGINT AS total_batch_runs,
        COALESCE(SUM(te.batch_records), 0)::BIGINT AS total_batch_records,
        COALESCE(SUM(te.api_calls), 0)::BIGINT AS total_api_calls,
        COALESCE(SUM(te.execution_time_ms), 0)::BIGINT AS total_execution_time_ms
    FROM telemetry_events te
    WHERE te.user_id = p_user_id
      AND te.event_date >= DATE_TRUNC('week', NOW())::DATE;

    -- All-time stats
    RETURN QUERY
    SELECT
        'alltime'::TEXT AS period,
        COALESCE(SUM(te.batch_runs), 0)::BIGINT AS total_batch_runs,
        COALESCE(SUM(te.batch_records), 0)::BIGINT AS total_batch_records,
        COALESCE(SUM(te.api_calls), 0)::BIGINT AS total_api_calls,
        COALESCE(SUM(te.execution_time_ms), 0)::BIGINT AS total_execution_time_ms
    FROM telemetry_events te
    WHERE te.user_id = p_user_id;
END;
$function$;

-- upsert_telemetry_events
CREATE OR REPLACE FUNCTION public.upsert_telemetry_events(p_events jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_event JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    FOR v_event IN SELECT * FROM jsonb_array_elements(p_events)
    LOOP
        INSERT INTO public.telemetry_events (
            user_id,
            event_date,
            environment_base_url,
            api_calls,
            batch_runs,
            batch_records,
            batch_successes,
            batch_failures,
            export_records,
            import_records,
            execution_time_ms,
            features_used,
            extension_version,
            vscode_version,
            os_platform
        ) VALUES (
            v_user_id,
            (v_event->>'event_date')::DATE,
            '',   -- never the address, whatever was sent
            COALESCE((v_event->>'api_calls')::INTEGER, 0),
            COALESCE((v_event->>'batch_runs')::INTEGER, 0),
            COALESCE((v_event->>'batch_records')::INTEGER, 0),
            COALESCE((v_event->>'batch_successes')::INTEGER, 0),
            COALESCE((v_event->>'batch_failures')::INTEGER, 0),
            COALESCE((v_event->>'export_records')::INTEGER, 0),
            COALESCE((v_event->>'import_records')::INTEGER, 0),
            COALESCE((v_event->>'execution_time_ms')::BIGINT, 0),
            COALESCE(v_event->'features_used', '{}'::JSONB),
            v_event->>'extension_version',
            v_event->>'vscode_version',
            v_event->>'os_platform'
        )
        ON CONFLICT (user_id, event_date, environment_base_url)
        DO UPDATE SET
            api_calls         = telemetry_events.api_calls         + EXCLUDED.api_calls,
            batch_runs        = telemetry_events.batch_runs        + EXCLUDED.batch_runs,
            batch_records     = telemetry_events.batch_records     + EXCLUDED.batch_records,
            batch_successes   = telemetry_events.batch_successes   + EXCLUDED.batch_successes,
            batch_failures    = telemetry_events.batch_failures    + EXCLUDED.batch_failures,
            export_records    = telemetry_events.export_records    + EXCLUDED.export_records,
            import_records    = telemetry_events.import_records    + EXCLUDED.import_records,
            execution_time_ms = telemetry_events.execution_time_ms + EXCLUDED.execution_time_ms,
            features_used     = telemetry_events.features_used || EXCLUDED.features_used,
            extension_version = EXCLUDED.extension_version,
            vscode_version    = EXCLUDED.vscode_version,
            os_platform       = EXCLUDED.os_platform,
            updated_at        = NOW();
    END LOOP;
END;
$function$;

