-- catalog_next_sequence
CREATE OR REPLACE FUNCTION public.catalog_next_sequence(p_endpoint_id text, p_array_path text DEFAULT ''::text, p_count integer DEFAULT 1, p_after bigint DEFAULT 0)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE
    reserved BIGINT;
BEGIN
    IF p_count IS NULL OR p_count < 1 OR p_count > 10000 THEN
        RAISE EXCEPTION 'p_count must be between 1 and 10000' USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.catalog_sequences (owner_user_id, endpoint_id, array_path, value)
    VALUES (auth.uid(), p_endpoint_id, COALESCE(p_array_path, ''), GREATEST(COALESCE(p_after, 0), 0) + p_count)
    ON CONFLICT (owner_user_id, endpoint_id, array_path)
    DO UPDATE SET value = GREATEST(public.catalog_sequences.value, COALESCE(p_after, 0)) + p_count
    RETURNING value INTO reserved;
    RETURN reserved;
END;
$function$;

-- user_settings_set
CREATE OR REPLACE FUNCTION public.user_settings_set(p_key text, p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_settings JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;
    IF p_key IS NULL OR p_key !~ '^[A-Za-z][A-Za-z0-9_-]*(\.[A-Za-z0-9_-]+){1,5}$' OR char_length(p_key) > 120 THEN
        RAISE EXCEPTION 'Invalid setting name' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.user_settings AS s (user_id, settings)
    VALUES (v_user_id, CASE WHEN p_value IS NULL OR p_value = 'null'::JSONB THEN '{}'::JSONB ELSE jsonb_build_object(p_key, p_value) END)
    ON CONFLICT (user_id) DO UPDATE SET
        settings = CASE
            WHEN p_value IS NULL OR p_value = 'null'::JSONB THEN s.settings - p_key
            ELSE s.settings || jsonb_build_object(p_key, p_value)
        END,
        updated_at = NOW()
    RETURNING settings INTO v_settings;
    RETURN v_settings;
END;
$function$;

-- get_environment_policies
CREATE OR REPLACE FUNCTION public.get_environment_policies(p_urls text[])
 RETURNS TABLE(environment_base_url text, enforced_environment_type text, lock_environment_type boolean, managed_by_label text, policy jsonb, policy_version integer, has_policy boolean, updated_at timestamp with time zone, vscode_only boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF auth.role() IS DISTINCT FROM 'authenticated' AND auth.role() IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'Authentication required'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    RETURN QUERY
    SELECT
        requested.url AS environment_base_url,
        ep.enforced_environment_type,
        ep.lock_environment_type,
        ep.managed_by_label,
        ep.policy,
        ep.policy_version,
        (ep.id IS NOT NULL) AS has_policy,
        ep.updated_at,
        COALESCE(ep.vscode_only, FALSE) AS vscode_only
    FROM (
        SELECT DISTINCT public.normalise_environment_url(u) AS url
        FROM UNNEST(COALESCE(p_urls, ARRAY[]::TEXT[])) AS u
    ) AS requested
    LEFT JOIN public.environment_policies ep
        ON ep.environment_base_url = requested.url
       AND ep.is_active
    WHERE requested.url IS NOT NULL;
END;
$function$;

-- allow_anonymous_policy_lookup
CREATE OR REPLACE FUNCTION public.allow_anonymous_policy_lookup(p_address text, p_limit integer DEFAULT 60)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    c INTEGER;
BEGIN
    IF auth.role() IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'Service role only' USING ERRCODE = 'insufficient_privilege';
    END IF;
    INSERT INTO public.anonymous_policy_lookups (address, window_start, count)
    VALUES (p_address, now(), 1)
    ON CONFLICT (address) DO UPDATE SET
        count = CASE WHEN public.anonymous_policy_lookups.window_start < now() - interval '1 minute'
                     THEN 1 ELSE public.anonymous_policy_lookups.count + 1 END,
        window_start = CASE WHEN public.anonymous_policy_lookups.window_start < now() - interval '1 minute'
                            THEN now() ELSE public.anonymous_policy_lookups.window_start END
    RETURNING public.anonymous_policy_lookups.count INTO c;
    IF random() < 0.01 THEN
        DELETE FROM public.anonymous_policy_lookups WHERE window_start < now() - interval '10 minutes';
    END IF;
    RETURN c <= p_limit;
END;
$function$;

-- catalog_return_sequence
CREATE OR REPLACE FUNCTION public.catalog_return_sequence(p_endpoint_id text, p_array_path text, p_reserved_to bigint, p_used_to bigint)
 RETURNS boolean
 LANGUAGE sql
AS $function$
    WITH returned AS (
        UPDATE public.catalog_sequences
        SET value = p_used_to
        WHERE owner_user_id = auth.uid()
          AND endpoint_id = p_endpoint_id
          AND array_path = COALESCE(p_array_path, '')
          AND value = p_reserved_to
          AND p_used_to >= 0
          AND p_used_to < p_reserved_to
        RETURNING 1
    )
    SELECT EXISTS (SELECT 1 FROM returned);
$function$;

-- catalog_reset_sequence
CREATE OR REPLACE FUNCTION public.catalog_reset_sequence(p_endpoint_id text, p_array_path text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE sql
AS $function$
    UPDATE public.catalog_sequences
    SET value = 0
    WHERE owner_user_id = auth.uid()
      AND endpoint_id = p_endpoint_id
      AND CASE
            WHEN p_array_path IS NULL THEN array_path = ''
            WHEN p_array_path = '*' THEN array_path <> ''
            ELSE array_path = p_array_path
          END;
$function$;

-- catalog_environment_has_secret_values
CREATE OR REPLACE FUNCTION public.catalog_environment_has_secret_values(item jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
    SELECT EXISTS (
        -- A header marked secret, with a value
        SELECT 1
        FROM jsonb_each(CASE WHEN jsonb_typeof(item->'headers') = 'object' THEN item->'headers' ELSE '{}'::jsonb END) AS h(name, header)
        WHERE jsonb_typeof(header) = 'object'
          AND header->'secret' = 'true'::jsonb
          AND COALESCE(header->>'value', '') <> ''
    ) OR EXISTS (
        -- A variable named secret, with a value
        SELECT 1
        FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(item->'secretVariables') = 'array' THEN item->'secretVariables' ELSE '[]'::jsonb END) AS v(name)
        WHERE COALESCE(item->'variables'->>v.name, '') <> ''
    );
$function$;

