--
-- Name: user_licenses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_licenses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    license_type text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    trial_started_at timestamp with time zone,
    trial_ends_at timestamp with time zone,
    subscription_started_at timestamp with time zone,
    subscription_ends_at timestamp with time zone,
    billing_period text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    is_lifetime boolean DEFAULT false NOT NULL,
    lifetime_license_number integer,
    cancel_at_period_end boolean DEFAULT false NOT NULL,
    CONSTRAINT user_licenses_billing_period_check CHECK ((billing_period = ANY (ARRAY['monthly'::text, 'annual'::text]))),
    CONSTRAINT user_licenses_license_type_check CHECK ((license_type = ANY (ARRAY['trial'::text, 'free'::text, 'user'::text, 'environment'::text]))),
    CONSTRAINT user_licenses_status_check CHECK ((status = ANY (ARRAY['active'::text, 'expired'::text, 'cancelled'::text, 'suspended'::text])))
);

