-- ---- functions that return a table's rows
-- increment_usage
CREATE OR REPLACE FUNCTION public.increment_usage(p_week_start date, p_batch_delta integer DEFAULT 0, p_export_delta integer DEFAULT 0, p_import_delta integer DEFAULT 0)
 RETURNS usage_tracking
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_row public.usage_tracking;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'increment_usage requires an authenticated user'
            USING ERRCODE = '42501';
    END IF;

    IF p_batch_delta < 0 OR p_export_delta < 0 OR p_import_delta < 0 THEN
        RAISE EXCEPTION 'usage deltas must be non-negative'
            USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.usage_tracking (user_id, week_start, batch_count, export_count, import_count)
    VALUES (v_user_id, p_week_start, p_batch_delta, p_export_delta, p_import_delta)
    ON CONFLICT (user_id, week_start) DO UPDATE
        SET batch_count  = usage_tracking.batch_count  + EXCLUDED.batch_count,
            export_count = usage_tracking.export_count + EXCLUDED.export_count,
            import_count = usage_tracking.import_count + EXCLUDED.import_count
    RETURNING * INTO v_row;

    RETURN v_row;
END;
$function$;

